const lessons=[{"sentences":[{"speaker":"A","text":"Good morning River Adventure Centre how can I help you today.","position":1,"audioStartSeconds":0,"audioEndSeconds":3.921375},{"speaker":"B","text":"Hello I would like to book a beginner canoe trip for next weekend.","position":2,"audioStartSeconds":4.121375,"audioEndSeconds":8.325875},{"speaker":"A","text":"We have availability on Saturday morning or Sunday afternoon.","position":3,"audioStartSeconds":8.525875,"audioEndSeconds":12.780375},{"speaker":"B","text":"Sunday afternoon was our original plan but Saturday morning is fine too.","position":4,"audioStartSeconds":12.980375,"audioEndSeconds":18.135791666666666},{"speaker":"A","text":"Saturday morning would be better because my friends are busy on Sunday.","position":5,"audioStartSeconds":18.335791666666665,"audioEndSeconds":22.639916666666668},{"speaker":"B","text":"That is wonderful and the cost is forty pounds per person.","position":6,"audioStartSeconds":22.839916666666667,"audioEndSeconds":26.937833333333334},{"speaker":"A","text":"Yes it includes a buoyancy aid and a paddle but you should bring spare clothes.","position":7,"audioStartSeconds":27.137833333333333,"audioEndSeconds":31.854333333333333},{"speaker":"B","text":"Where should we meet our instructor before the session starts.","position":8,"audioStartSeconds":32.05433333333333,"audioEndSeconds":36.0105},{"speaker":"A","text":"Please meet by the wooden boathouse ten minutes before the lesson.","position":9,"audioStartSeconds":36.2105,"audioEndSeconds":40.256875},{"speaker":"B","text":"Should I pay online now or bring cash on the day.","position":10,"audioStartSeconds":40.456875,"audioEndSeconds":44.181125},{"speaker":"A","text":"You can pay by card when you arrive at the reception desk.","position":11,"audioStartSeconds":44.381125,"audioEndSeconds":48.23291666666667},{"speaker":"B","text":"Thank you for all your helpful information today.","position":12,"audioStartSeconds":48.432916666666664,"audioEndSeconds":51.88616666666667}],"questions":[{"prompt":"Chosen trip day: ______","answer":"Saturday morning","evidenceSentence":5,"evidence":"Saturday morning would be better","explanation":"Người nói chọn buổi sáng thứ bảy vì bạn bè bận vào chủ nhật, loại bỏ ý định chủ nhật ban đầu."},{"prompt":"Cost per person: ______","answer":"forty pounds","evidenceSentence":6,"evidence":"cost is forty pounds per person","explanation":"Chi phí là bốn mươi bảng một người."},{"prompt":"Extra item to bring: ______","answer":"spare clothes","evidenceSentence":7,"evidence":"bring spare clothes","explanation":"Trung tâm yêu cầu mang theo quần áo dự phòng."},{"prompt":"Meeting location: ______","answer":"wooden boathouse","evidenceSentence":9,"evidence":"meet by the wooden boathouse","explanation":"Điểm hẹn là ở nhà thuyền bằng gỗ."},{"prompt":"Arrival time before lesson: ______","answer":"ten minutes","evidenceSentence":9,"evidence":"ten minutes before the lesson","explanation":"Mọi người cần đến trước buổi học mười phút."},{"prompt":"Payment location: ______","answer":"reception desk","evidenceSentence":11,"evidence":"arrive at the reception desk","explanation":"Khách hàng có thể thanh toán tại quầy lễ tân khi đến nơi."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
